mapper.select:
select DISTINCT u.id,u.user_name,u.pass_word,u.emp_name,u.emp_no,u.modify_emp,u.modify_emp_no,u.delete_falg,u.factory_id,u.power_factory_id from safety_sys_user u,safety_sys_user_role ur,safety_sys_role r where u.id = ur.user_id and u.delete_falg = 0 and ur.role_id = r.id
and FIND_IN_SET (#{factoryId},u.factory_id)
and FIND_IN_SET (#{powerFactoryId},u.power_factory_id)
and
FIND_IN_SET (#{item},u.power_factory_id)
and r.id = #{roleId}
and r.role_name = #{roleName}
and r.role_name in
#{item}
and u.user_name = #{userName}

mapper.update:
insert into safety.safety_sys_user (emp_no,emp_name,user_name,modify_emp,modify_emp_no,create_time,update_time,delete_falg) select emp_no,emp_name,emp_login,'门禁系统管理员','system',now(),now(),0 from safety.safety_employee_message sem where sem.status = 'NORMAL' and emp_no in
#{item}
and emp_no not in (select emp_no from safety.safety_sys_user ssu where ssu.delete_falg = 0)
